              <p hlmDialogDescription>
                This removes {{ hero.name }} from the roster. Their record is not kept after you retire them.
              </p>
            </hlm-dialog-header>
            <hlm-dialog-footer>
              <button hlmBtn variant="outline" type="button" hlmDialogClose>Cancel</button>
              <button hlmBtn variant="destructive" type="button" (click)="retireDialog.close(); vm.retire()">
                Retire hero
              </button>
            </hlm-dialog-footer>
          </hlm-dialog-content>
        </hlm-dialog>
      </div>

      @if (!vm.canDeploy()) {
        <p hlmMuted class="hero-detail__hint">Only active heroes can be deployed.</p>
      }
    </header>

    <hlm-tabs tab="overview" class="hero-detail__tabs">
      <hlm-tabs-list class="hero-detail__tabs-list">
        <button hlmTabsTrigger="overview">Overview</button>
        <button hlmTabsTrigger="powers">Powers</button>
        <button hlmTabsTrigger="missions">Missions</button>
        <button hlmTabsTrigger="edit">Edit</button>
      </hlm-tabs-list>

      <div hlmTabsContent="overview" class="hero-detail__panel">
        <div class="hero-detail__columns">
          <section hlmCard>
            <header hlmCardHeader>
              <h2 hlmCardTitle>Field summary</h2>
            </header>
            <div hlmCardContent class="hero-detail__summary">
              <p hlmSmall>{{ vm.summary() }}</p>
              <dl class="hero-detail__stats">
                <div class="hero-detail__stat">
                  <dt hlmMuted>Missions</dt>
                  <dd hlmLarge>{{ vm.record().missions }}</dd>
                </div>
                <div class="hero-detail__stat">
                  <dt hlmMuted>Success rate</dt>
                  <dd hlmLarge>{{ vm.record().rate }}%</dd>
                </div>
                <div class="hero-detail__stat">
                  <dt hlmMuted>Power index</dt>
                  <dd hlmLarge>{{ hero.powerIndex }}</dd>
                </div>
              </dl>
            </div>
          </section>

          <section hlmCard>
            <header hlmCardHeader>
              <h2 hlmCardTitle>Dossier</h2>
            </header>
            <div hlmCardContent>
              <dl class="hero-detail__dossier">
                @for (entry of vm.dossier(); track entry.label) {
                  <div class="hero-detail__pair">
                    <dt hlmMuted>{{ entry.label }}</dt>
                    <dd hlmSmall>{{ entry.value }}</dd>
                  </div>
                }
              </dl>
            </div>
          </section>
        </div>
      </div>

      <div hlmTabsContent="powers" class="hero-detail__panel">
        <div class="hero-detail__columns">
          <section hlmCard>
            <header hlmCardHeader>
              <h2 hlmCardTitle>Power index</h2>
            </header>
            <div hlmCardContent>
              <app-power-meter [value]="hero.powerIndex" [label]="'Power index for ' + hero.name" />
            </div>
          </section>

          <section hlmCard>
            <header hlmCardHeader>
              <h2 hlmCardTitle>Abilities</h2>
            </header>
            <div hlmCardContent class="hero-detail__abilities">
              @for (ability of vm.abilities(); track ability) {
                <span hlmBadge variant="secondary">{{ ability }}</span>
              }
            </div>
          </section>
        </div>
      </div>

      <div hlmTabsContent="missions" class="hero-detail__panel">
        <section hlmCard>
          <header hlmCardHeader>
            <h2 hlmCardTitle>Mission record</h2>
          </header>
          <div hlmCardContent class="hero-detail__record">
            <p hlmSmall>
              {{ vm.record().missions }} missions on record: {{ vm.record().won }} won, {{ vm.record().lost }} lost.
            </p>
            <span hlmBadge [variant]="vm.record().rateVariant">{{ vm.record().rate }}% success</span>
          </div>
        </section>
      </div>

      <div hlmTabsContent="edit" class="hero-detail__panel">
        <section hlmCard>
          <header hlmCardHeader>
            <h2 hlmCardTitle>Edit hero</h2>
          </header>
          <div hlmCardContent>
            <form class="hero-detail__form" (submit)="$event.preventDefault(); vm.save()">
              <div hlmField class="hero-detail__field hero-detail__field--wide">
                <label hlmFieldLabel for="hero-name">{{ vm.meta.name.label }}</label>
                <input hlmInput id="hero-name" class="hero-detail__control" [formField]="vm.heroForm.name" />
                @for (error of vm.heroForm.name().errors(); track error.kind) {
                  <hlm-field-error>{{ error.message }}</hlm-field-error>
                }
              </div>

              <div hlmField class="hero-detail__field hero-detail__field--wide">
                <label hlmFieldLabel for="hero-alias">{{ vm.meta.alias.label }}</label>
                <input hlmInput id="hero-alias" class="hero-detail__control" [formField]="vm.heroForm.alias" />
                @for (error of vm.heroForm.alias().errors(); track error.kind) {
                  <hlm-field-error>{{ error.message }}</hlm-field-error>
                }
              </div>

              <div hlmField class="hero-detail__field">
                <label hlmFieldLabel for="hero-power-class">{{ vm.meta.powerClass.label }}</label>
                <hlm-select
                  class="hero-detail__control"
                  [value]="vm.draft().powerClass"
                  (valueChange)="vm.setPowerClass($event)"
                >
                  <hlm-select-trigger buttonId="hero-power-class">
                    <hlm-select-value />
                  </hlm-select-trigger>
                  <hlm-select-content *hlmSelectPortal>
                    @for (option of vm.meta.powerClass.options ?? []; track option.value) {
                      <hlm-select-item [value]="option.value">{{ option.label }}</hlm-select-item>
                    }
                  </hlm-select-content>
                </hlm-select>
                @for (error of vm.heroForm.powerClass().errors(); track error.kind) {
                  <hlm-field-error>{{ error.message }}</hlm-field-error>
                }
              </div>

              <div hlmField class="hero-detail__field">
                <label hlmFieldLabel for="hero-power-index">{{ vm.meta.powerIndex.label }}</label>
                <input
                  hlmInput
                  id="hero-power-index"
                  type="number"
                  class="hero-detail__control"
                  [formField]="vm.heroForm.powerIndex"
                />
                @for (error of vm.heroForm.powerIndex().errors(); track error.kind) {
                  <hlm-field-error>{{ error.message }}</hlm-field-error>
                }
              </div>

              <div hlmField class="hero-detail__field">
                <label hlmFieldLabel for="hero-clearance">{{ vm.meta.clearance.label }}</label>
                <hlm-select
                  class="hero-detail__control"
                  [value]="vm.draft().clearance"
                  (valueChange)="vm.setClearance($event)"
                >
                  <hlm-select-trigger buttonId="hero-clearance">
                    <hlm-select-value />
                  </hlm-select-trigger>
                  <hlm-select-content *hlmSelectPortal>
                    @for (option of vm.meta.clearance.options ?? []; track option.value) {
                      <hlm-select-item [value]="option.value">{{ option.label }}</hlm-select-item>
                    }
                  </hlm-select-content>
                </hlm-select>
                @for (error of vm.heroForm.clearance().errors(); track error.kind) {
                  <hlm-field-error>{{ error.message }}</hlm-field-error>
                }
              </div>

              <div class="hero-detail__form-actions">
                @if (vm.saved()) {
                  <p hlmSmall role="status" class="hero-detail__notice">
                    <ng-icon hlmIcon name="lucideCheck" tone="success" />
                    Changes saved.
                  </p>
                }
                <button hlmBtn variant="outline" type="button" (click)="vm.reset()">Cancel</button>
                <button hlmBtn type="submit">Save changes</button>
              </div>
            </form>
          </div>
        </section>
      </div>
    </hlm-tabs>
  } @else {
    <section class="hero-detail__missing">
      <h1 hlmH1>No hero at this ID</h1>
      <p hlmMuted>The roster has no hero with this ID. They may have been retired.</p>
    </section>
  }
</section>
